import java.io.*;
import java.util.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static long readLong() throws IOException {
        int c = in.read();
        while (c != -1 && (c < '0' || c > '9')) c = in.read();
        long x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) readLong();
        int[] a = new int[n];  // heights fit in a non-negative int
        for (int i = 0; i < n; i++) a[i] = (int) readLong();
        Arrays.sort(a);
        // Each pile needs one step per distinct height below it: sum of ranks.
        long answer = 0, rank = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0 && a[i] != a[i - 1]) rank++;
            answer += rank;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readUint() uint32 {
	c, err := reader.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = reader.ReadByte()
	}
	var x uint32
	for err == nil && c >= '0' && c <= '9' {
		x = x*10 + uint32(c-'0')
		c, err = reader.ReadByte()
	}
	return x
}

func main() {
	n := int(readUint())
	a := make([]uint32, n)
	for i := range a {
		a[i] = readUint()
	}
	slices.Sort(a)
	// Each pile needs one step per distinct height below it: sum of ranks.
	var answer, rank int64
	for i := range a {
		if i > 0 && a[i] != a[i-1] {
			rank++
		}
		answer += rank
	}
	fmt.Println(answer)
}
